package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.io.File;import java.util.concurrent.*;

public class DocumentActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private VaultRepository repo;private JSONObject doc;private LinearLayout page;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);if(!Session.valid()){finish();return;}repo=new VaultRepository(this);shell();load();}
 private void shell(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=Ui.column(this);page.setPadding(Ui.dp(this,18),Ui.dp(this,14),Ui.dp(this,18),Ui.dp(this,28));page.setBackgroundColor(Ui.BG);scroll.addView(page);setContentView(scroll);}
 private void load(){String id=getIntent().getStringExtra("id");io.execute(()->{try{doc=repo.get(id);if(doc==null)throw new IllegalStateException();runOnUiThread(this::render);}catch(Exception e){runOnUiThread(()->{Ui.toast(this,"Document not found");finish();});}});}
 private void render(){page.removeAllViews();LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView back=Ui.text(this,"‹",38,Ui.INK);back.setGravity(Gravity.CENTER);back.setContentDescription("Back");back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));LinearLayout titles=Ui.column(this);titles.addView(Ui.title(this,doc.optString("title"),23));titles.addView(Ui.text(this,doc.optString("category","Other")+" · Encrypted",13,Ui.TEAL));bar.addView(titles,new LinearLayout.LayoutParams(0,-2,1));TextView menu=Ui.text(this,"⋮",30,Ui.INK);menu.setGravity(Gravity.CENTER);menu.setContentDescription("Document Options");menu.setOnClickListener(v->options(menu));bar.addView(menu,new LinearLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,46)));page.addView(bar);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);boolean originalWord=doc.optString("originalMime").contains("wordprocessingml"),hasPdfPreview="application/pdf".equals(doc.optString("previewMime"));TextView pdf=Ui.pill(this,originalWord?"SHARE":"PDF",Ui.NAVY),word=Ui.pill(this,originalWord?"OPEN WORD":"WORD",Ui.TEAL),print=Ui.pill(this,"PRINT",0xff6b7f79);pdf.setOnClickListener(v->{if(originalWord)shareOriginalWord();else layoutChoice("pdf",false);});word.setOnClickListener(v->{if(originalWord)openOriginalWord();else layoutChoice("docx",false);});print.setOnClickListener(v->layoutChoice("pdf",true));if(originalWord)print.setVisibility(View.GONE);for(TextView action:new TextView[]{pdf,word,print}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,45),originalWord&&action==word?1.2f:1);p.setMargins(Ui.dp(this,4),Ui.dp(this,18),Ui.dp(this,4),Ui.dp(this,16));actions.addView(action,p);}page.addView(actions);String privacyText=doc.optString("original").isEmpty()?"Decrypted only for this private preview. Exports are created only when you choose an action above.":hasPdfPreview?"This accurate preview comes from your PDF companion. Open Word uses the untouched original DOCX.":"The original Word file is encrypted unchanged. No content preview is generated.";TextView privacy=Ui.text(this,privacyText,12,Ui.MUTED);privacy.setGravity(Gravity.CENTER);privacy.setPadding(Ui.dp(this,12),0,Ui.dp(this,12),Ui.dp(this,14));page.addView(privacy);addDetailsSummary();if(originalWord&&!hasPdfPreview){wordOriginalCard();return;}JSONArray pages=doc.optJSONArray("pages");for(int i=0;pages!=null&&i<pages.length();i++){int index=i;FrameLayout frame=new FrameLayout(this);frame.setPadding(Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8));frame.setBackground(Ui.stroke(Color.WHITE,Ui.dp(this,1),0xffd2dcda,Ui.dp(this,16)));frame.setElevation(Ui.dp(this,3));ProgressBar loading=new ProgressBar(this);frame.addView(loading,new FrameLayout.LayoutParams(Ui.dp(this,38),Ui.dp(this,38),Gravity.CENTER));TextView number=Ui.text(this,(i==0&&pages.length()==2?"FRONT":i==1&&pages.length()==2?"BACK":"PAGE "+(i+1)),11,Color.WHITE);number.setGravity(Gravity.CENTER);number.setTypeface(null,android.graphics.Typeface.BOLD);number.setBackground(Ui.bg(Ui.NAVY,Ui.dp(this,12)));FrameLayout.LayoutParams np=new FrameLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,25),Gravity.TOP|Gravity.START);np.setMargins(Ui.dp(this,13),Ui.dp(this,13),0,0);frame.addView(number,np);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,Ui.dp(this,430));fp.bottomMargin=Ui.dp(this,14);page.addView(frame,fp);io.execute(()->loadPage(frame,loading,index));}}
 private void wordOriginalCard(){LinearLayout card=Ui.column(this);card.setGravity(Gravity.CENTER);card.setPadding(Ui.dp(this,24),Ui.dp(this,30),Ui.dp(this,24),Ui.dp(this,30));card.setBackground(Ui.stroke(0xfff7faff,Ui.dp(this,1),0xffb8cbea,Ui.dp(this,20)));card.setElevation(Ui.dp(this,4));TextView mark=Ui.title(this,"W",54);mark.setTextColor(Color.WHITE);mark.setGravity(Gravity.CENTER);mark.setBackground(Ui.bg(0xff185abd,Ui.dp(this,18)));card.addView(mark,new LinearLayout.LayoutParams(Ui.dp(this,84),Ui.dp(this,84)));TextView heading=Ui.title(this,"Original Word Document",22);heading.setTextColor(0xff10253f);heading.setGravity(Gravity.CENTER);heading.setPadding(0,Ui.dp(this,18),0,Ui.dp(this,6));card.addView(heading);TextView message=Ui.text(this,"This is an encrypted, byte-for-byte copy. Open it in Word to see its original fonts, tables, margins, headers, columns, spacing, and page breaks.",14,Ui.MUTED);message.setGravity(Gravity.CENTER);message.setLineSpacing(0,1.18f);card.addView(message);TextView open=Ui.pill(this,"Open Original In Word",0xff185abd);open.setOnClickListener(v->openOriginalWord());LinearLayout.LayoutParams button=new LinearLayout.LayoutParams(-1,Ui.dp(this,52));button.topMargin=Ui.dp(this,22);card.addView(open,button);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.setMargins(0,Ui.dp(this,8),0,Ui.dp(this,16));page.addView(card,params);}
 private void loadPage(FrameLayout frame,View loading,int index){try{byte[] data=repo.page(doc,index);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,bounds);int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>1800)sample*=2;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,o);runOnUiThread(()->{if(isFinishing()){bitmap.recycle();return;}ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_CENTER);frame.addView(image,0,new FrameLayout.LayoutParams(-1,-1));frame.removeView(loading);});}catch(Exception e){runOnUiThread(()->{frame.removeView(loading);TextView error=Ui.text(this,"Could Not Decrypt This Page",14,0xffb33a3a);error.setGravity(Gravity.CENTER);frame.addView(error,new FrameLayout.LayoutParams(-1,-1));});}}
 private void layoutChoice(String format,boolean print){String storedMime=doc.optString("originalMime");if(("docx".equals(format)&&storedMime.contains("wordprocessingml"))||("pdf".equals(format)&&"application/pdf".equals(storedMime))){export(format,false,print);return;}boolean multiple=doc.optJSONArray("pages").length()>1;if(!multiple){export(format,false,print);return;}String[] items={"Front And Back Centered On One Page","Place Each Side On Its Own Page"};new AlertDialog.Builder(this).setTitle(print?"Print Layout":"Export Layout").setSingleChoiceItems(items,0,null).setNegativeButton("Cancel",null).setPositiveButton("Continue",(d,w)->export(format,((AlertDialog)d).getListView().getCheckedItemPosition()==0,print)).show();}
 private void export(String format,boolean together,boolean print){ProgressDialog wait=new ProgressDialog(this);wait.setMessage(print?"Preparing print copy…":"Creating secure export…");wait.setCancelable(false);wait.show();io.execute(()->{try{DocumentExporter ex=new DocumentExporter(this);String storedMime=doc.optString("originalMime");boolean exact=("docx".equals(format)&&storedMime.contains("wordprocessingml"))||("pdf".equals(format)&&"application/pdf".equals(storedMime));File f=exact?ex.original(doc):format.equals("docx")?ex.docx(doc,together):ex.pdf(doc,together);String mime=exact?storedMime:format.equals("docx")?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"application/pdf";runOnUiThread(()->{wait.dismiss();if(print&&"application/pdf".equals(mime))ex.print(this,f,doc.optString("title","Document"));else if(print){Ui.toast(this,"Open The Original Word File In Word To Print It Without Changing Its Layout");ex.share(f,mime);}else ex.share(f,mime);});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could not create the export");});}});}
 private void openOriginalWord(){ProgressDialog wait=new ProgressDialog(this);wait.setMessage("Opening Original In Word…");wait.setCancelable(false);wait.show();io.execute(()->{try{DocumentExporter exporter=new DocumentExporter(this);File original=exporter.original(doc);String mime=doc.optString("originalMime","application/vnd.openxmlformats-officedocument.wordprocessingml.document");runOnUiThread(()->{wait.dismiss();try{exporter.open(original,mime);}catch(Exception error){Ui.toast(this,"Install Microsoft Word Or Another DOCX App To Open This File");}});}catch(Exception error){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Open The Original Word File");});}});}
 private void shareOriginalWord(){ProgressDialog wait=new ProgressDialog(this);wait.setMessage("Preparing Original Word File…");wait.setCancelable(false);wait.show();io.execute(()->{try{DocumentExporter exporter=new DocumentExporter(this);File original=exporter.original(doc);String mime=doc.optString("originalMime","application/vnd.openxmlformats-officedocument.wordprocessingml.document");runOnUiThread(()->{wait.dismiss();exporter.share(original,mime);});}catch(Exception error){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Share The Original Word File");});}});}
 private void options(View anchor){PopupWindow pop=new PopupWindow(this);LinearLayout list=Ui.column(this);list.setPadding(Ui.dp(this,6),Ui.dp(this,7),Ui.dp(this,6),Ui.dp(this,7));String[] names={"Document Details","Edit And Recrop","Rename Document","Change Category","Delete From Wallet"};for(String name:names){TextView item=Ui.text(this,name,15,name.startsWith("Delete")?0xffe45b52:Ui.INK);item.setPadding(Ui.dp(this,18),0,Ui.dp(this,18),0);item.setOnClickListener(v->{pop.dismiss();if(name.startsWith("Document"))details();else if(name.startsWith("Edit"))choosePageToEdit();else if(name.startsWith("Rename"))edit(false);else if(name.startsWith("Change"))edit(true);else confirmDelete();});list.addView(item,new LinearLayout.LayoutParams(Ui.dp(this,224),Ui.dp(this,50)));}pop.setContentView(list);pop.setWidth(Ui.dp(this,236));pop.setHeight(-2);Ui.polishPopup(this,pop,list,26);pop.showAsDropDown(anchor,-Ui.dp(this,190),Ui.dp(this,4));}
 private void choosePageToEdit(){JSONArray pages=doc.optJSONArray("pages");int total=pages==null?0:pages.length();if(total<=1){openEditor(0);return;}String[] choices=new String[total];for(int i=0;i<total;i++)choices[i]=(total==2?(i==0?"Front":"Back"):"Page "+(i+1));new AlertDialog.Builder(this).setTitle("Choose A Page To Edit").setItems(choices,(d,i)->openEditor(i)).show();}
 private void openEditor(int pageIndex){startActivity(new Intent(this,EditDocumentActivity.class).putExtra("id",doc.optString("id")).putExtra("page",pageIndex));}
 private void edit(boolean categoryOnly){if(categoryOnly){String[] values={"ID / Permit","Certificates","Bank Cards","Documents"};new AlertDialog.Builder(this).setTitle("Change Category").setItems(values,(d,i)->saveEdit(doc.optString("title"),values[i])).show();return;}EditText name=Ui.field(this,"Document name",false);name.setText(doc.optString("title"));FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(name,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Rename Document").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty()){name.setError("Enter a name");return;}dialog.dismiss();saveEdit(n,doc.optString("category","Other"));}));dialog.show();}
 private void saveEdit(String title,String category){io.execute(()->{try{repo.rename(doc.getString("id"),title,category);doc.put("title",title).put("category",category);runOnUiThread(this::render);}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could not update the document"));}});}
 private void addDetailsSummary(){String issuer=doc.optString("issuer"),number=doc.optString("documentNumber"),issued=doc.optString("issueDate"),expiry=doc.optString("expiryDate"),tags=doc.optString("tags");if(issuer.isEmpty()&&number.isEmpty()&&issued.isEmpty()&&expiry.isEmpty()&&tags.isEmpty())return;LinearLayout card=Ui.column(this);card.setPadding(Ui.dp(this,15),Ui.dp(this,12),Ui.dp(this,15),Ui.dp(this,12));card.setBackground(Ui.stroke(0xffeef8f5,Ui.dp(this,1),0xffc9e4dc,Ui.dp(this,15)));card.addView(Ui.title(this,"Document Details",15));if(!issuer.isEmpty())card.addView(Ui.text(this,"Issuer: "+issuer,13,Ui.MUTED));if(!number.isEmpty())card.addView(Ui.text(this,"Number: •••• "+number.substring(Math.max(0,number.length()-4)),13,Ui.MUTED));if(!issued.isEmpty())card.addView(Ui.text(this,"Issued: "+issued,13,Ui.MUTED));if(!expiry.isEmpty())card.addView(Ui.text(this,"Expires: "+expiry,13,0xff9a5a00));if(!tags.isEmpty())card.addView(Ui.text(this,"Tags: "+tags,13,Ui.TEAL));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=Ui.dp(this,14);page.addView(card,p);}
 private void details(){ScrollView scroll=new ScrollView(this);LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,6),Ui.dp(this,18),Ui.dp(this,8));EditText issuer=detailField(box,"Issuer or organization",doc.optString("issuer")),number=detailField(box,"Document number",doc.optString("documentNumber")),issued=detailField(box,"Issue date (DD/MM/YYYY)",doc.optString("issueDate")),expires=detailField(box,"Expiry date (DD/MM/YYYY)",doc.optString("expiryDate")),tags=detailField(box,"Tags, separated by commas",doc.optString("tags")),notes=detailField(box,"Private notes",doc.optString("notes"));scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Document Details").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{if(!validDate(issued)||!validDate(expires))return;String a=issuer.getText().toString().trim(),b=number.getText().toString().trim(),c=issued.getText().toString().trim(),d=expires.getText().toString().trim(),e=tags.getText().toString().trim(),f=notes.getText().toString().trim();io.execute(()->{try{repo.updateDetails(doc.getString("id"),a,b,c,d,e,f);doc.put("issuer",a).put("documentNumber",b).put("issueDate",c).put("expiryDate",d).put("tags",e).put("notes",f);ExpiryScheduler.schedule(this,doc);runOnUiThread(()->{dialog.dismiss();render();});}catch(Exception error){runOnUiThread(()->Ui.toast(this,"Could Not Save Document Details"));}});}));dialog.show();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private EditText detailField(LinearLayout box,String hint,String value){EditText field=Ui.field(this,hint,false);field.setText(value);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));p.bottomMargin=Ui.dp(this,9);box.addView(field,p);return field;}
 private boolean validDate(EditText field){String value=field.getText().toString().trim();if(value.isEmpty())return true;try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("dd/MM/yyyy",java.util.Locale.US);f.setLenient(false);f.parse(value);return true;}catch(Exception e){field.setError("Use DD/MM/YYYY");return false;}}
 private void confirmDelete(){new AlertDialog.Builder(this).setTitle("Delete Document?").setMessage("This permanently removes every encrypted page from this phone. This cannot be undone.").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->io.execute(()->{try{repo.delete(doc.getString("id"));runOnUiThread(()->{Ui.toast(this,"Document deleted");finish();});}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could not delete the document"));}})).show();}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();else if(doc!=null)load();}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
